(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.015+t*0.3)*22 + Math.cos(y*0.012-t*0.2)*16 + Math.sin((x+y)*0.007+t*0.5)*12 + Math.sin(x*0.025+y*0.02+t*1.2)*5;
  const wy = Math.cos(y*0.015-t*0.25)*22 + Math.sin(x*0.013+t*0.35)*16 + Math.cos((x-y)*0.008-t*0.45)*12 + Math.cos(x*0.022-y*0.018-t*1.1)*5;
  const sx = x + wx, sy = y + wy;
  const wells = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.95],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.1],
    [60+Math.sin(t*0.45)*60, 40+Math.cos(t*0.65)*40, 0.14, 2.1, 0.65],
    [420+Math.cos(t*0.55)*70, 200+Math.sin(t*0.75)*50, 0.11, 1.8, 0.8]
  ];
  let aS=0, iS=0, potential=0, kinetic=0;
  for(const [sX,sY,f,sp,mass] of wells){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const invD=mass/(d+5);
    potential+=invD;
    aS+=Math.sin(d*f-t*sp)*(0.5+invD*0.5);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*(0.5+invD*0.3);
    kinetic+=Math.cos(d*f*1.3-t*sp*1.1)*invD;
  }
  const n=wells.length, act=aS/n, inh=iS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+t*3)*Math.cos(sy*0.06-t*2.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*5+t*0.8))*0.33;
  const react2=Math.sin(act*2.5-inh*1.8+t*0.5)*Math.cos(act+inh-t*0.3);
  const totalEnergy=potential*0.3+Math.abs(kinetic)*0.2;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+react2*0.4+totalEnergy)*2.5);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const raw=reaction*0.7+cell*0.3;
  const sharpened=Math.tanh(raw*3.2);
  const v=sharpened*0.5+0.5;
  const pal=[[2,2,18],[8,0,55],[25,0,130],[0,160,255],[0,255,170],[255,255,80],[255,60,130],[255,30,210],[100,0,70],[2,2,18]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const edgeGlow=Math.pow(Math.abs(reaction),0.5);
  const lum=0.65+edgeGlow*0.65+Math.pow(Math.abs(raw),0.8)*0.35;
  const bloom=Math.max(0,Math.abs(reaction)-0.55)*2.8;
  const r=(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum+bloom*50;
  const g=(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum+bloom*70;
  const b=(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum+bloom*90;
  return [Math.min(255,r)|0, Math.min(255,g)|0, Math.min(255,b)|0];
}
